<template><ContentWrap><h2>编导时效配置</h2><el-alert title="时效调整只影响新建业务，不改写历史预约和定位卡。" type="info" show-icon class="mb-20px"/><el-form v-if="form" v-loading="loading" label-width="180px" class="max-w-600px"><el-form-item label="采访预约默认时限"><el-input-number v-model="form.interviewAppointmentHours" :min="1" :max="720"/><span class="ml-8px">小时</span></el-form-item><el-form-item label="定位任务默认时限"><el-input-number v-model="form.positioningDueHours" :min="1" :max="720"/><span class="ml-8px">小时</span></el-form-item><el-form-item label="试运行默认周期"><el-input-number v-model="form.trialDays" :min="1" :max="365"/><span class="ml-8px">天</span></el-form-item><el-button type="primary" v-hasPermi="['zsjos:director-config:update']" @click="save">保存</el-button></el-form><el-empty v-else description="配置加载失败"><el-button @click="load">重试</el-button></el-empty></ContentWrap></template>
<script setup lang="ts">import * as Api from '@/api/zsjos/director';import {useMessage} from '@/hooks/web/useMessage';const message=useMessage(),loading=ref(false),form=ref<Api.DirectorConfig>();const load=async()=>{loading.value=true;try{form.value=await Api.getDirectorConfig()}catch{form.value=undefined}finally{loading.value=false}};const save=async()=>{if(!form.value)return;await Api.updateDirectorConfig(form.value);message.success('已保存');await load()};onMounted(load)</script>
